<template>
  <div class="form">
    <div class="form-group">
      <div class="form-input">
        <i class="fas fa-user"></i>
        <input v-model="username" type="text" autocomplete='off' spellcheck='false' autocorrect='off' placeholder="Username">
      </div>
    </div>
    <div class="form-group">
      <div class="form-input">
        <i class="fas fa-envelope"></i>
        <input v-model="mail" type="email" autocomplete='off' spellcheck='false' autocorrect='off' placeholder="Mail">
      </div>
    </div>
    <div class="form-group">
      <div class="form-input">
        <i class="fas fa-lock"></i>
        <input v-model="password" type="password" autocomplete='off' spellcheck='false' autocorrect='off' placeholder="Password">
      </div>
    </div>
    <button class="form-button" @click="submit" :disabled="loading" ><i v-if="loading" class="fas fa-spinner fa-spin"></i> Register</button>
  </div>
  <div class="ask">
    Already have an account? <strong style="cursor: pointer;" @click='$emit("toggle", true)'>Login</strong>
  </div>
</template>

<script>
export default {
  name: "Register",
  emits: ['toggle'],
  methods: {
    submit() {
      this.loading = true;
      setTimeout(() => { this.loading = false }, 1000)

      // eslint-disable-next-line no-undef
      mp.trigger('registerInformationToServer', (this.mail.length < 1 ? 'N/A' : this.mail), this.username, this.password);
    }
  },
  data() {
    return {
      username: "",
      password: "",
      mail: "",
      loading: false
    }
  }
}
</script>

<style scoped lang="scss">
@import '~@/assets/form.scss';
</style>